"use strict";

const { Sequelize, DataTypes, Model } = require("sequelize");
const { DATABASE_CONFIG } = require("./config");

const MODEL_NAMES = {
  user: "User",
  article: "Article",
  comment: "Comment",
};
const FOREIGN_KEYS = {
  user: "userId",
  article: "articleId",
};
const ASSOCIATION_ALIASES = {
  author: "author",
};
const HIDDEN_ATTRIBUTES = {
  user: ["id", "updatedAt", "createdAt"],
  article: ["id", FOREIGN_KEYS.user],
  comment: [FOREIGN_KEYS.article, FOREIGN_KEYS.user],
};

const sequelize = new Sequelize(DATABASE_CONFIG);

function serializeWithout(model, hiddenAttributes) {
  const data = { ...model.get() };

  hiddenAttributes.forEach((attribute) => {
    delete data[attribute];
  });

  return data;
}

function modelOptions(modelName) {
  return { sequelize, modelName };
}

class User extends Model {
  static associate() {
    this.hasMany(Article, {
      foreignKey: FOREIGN_KEYS.user,
      onDelete: "CASCADE",
    });
    this.hasMany(Comment, { foreignKey: FOREIGN_KEYS.user });
  }

  toJSON() {
    return serializeWithout(this, HIDDEN_ATTRIBUTES.user);
  }
}

class Article extends Model {
  static associate() {
    this.belongsTo(User, {
      foreignKey: FOREIGN_KEYS.user,
      as: ASSOCIATION_ALIASES.author,
    });
    this.hasMany(Comment, {
      foreignKey: FOREIGN_KEYS.article,
      onDelete: "CASCADE",
    });
  }

  toJSON() {
    return serializeWithout(this, HIDDEN_ATTRIBUTES.article);
  }
}

class Comment extends Model {
  static associate() {
    this.belongsTo(Article, { foreignKey: FOREIGN_KEYS.article });
    this.belongsTo(User, {
      as: ASSOCIATION_ALIASES.author,
      foreignKey: FOREIGN_KEYS.user,
    });
  }

  toJSON() {
    return serializeWithout(this, HIDDEN_ATTRIBUTES.comment);
  }
}

function defineModels() {
  User.init(
    { username: DataTypes.STRING },
    modelOptions(MODEL_NAMES.user),
  );

  Article.init(
    { slug: DataTypes.STRING },
    modelOptions(MODEL_NAMES.article),
  );

  Comment.init(
    {
      id: {
        allowNull: false,
        autoIncrement: true,
        primaryKey: true,
        type: DataTypes.INTEGER,
      },
      body: DataTypes.TEXT,
    },
    modelOptions(MODEL_NAMES.comment),
  );
}

function associateModels() {
  User.associate();
  Article.associate();
  Comment.associate();
}

defineModels();
associateModels();

module.exports = {
  sequelize,
  User,
  Article,
  Comment,
  ASSOCIATION_ALIASES,
};

const { SEED_DATA } = require("./config");
const { User, Article, Comment } = require("./models");

async function seed() {
  const [user] = await User.findOrCreate({
    where: SEED_DATA.user,
    defaults: SEED_DATA.user,
  });

  const [article] = await Article.findOrCreate({
    where: SEED_DATA.article,
    defaults: { ...SEED_DATA.article, userId: user.id },
  });

  const count = await Comment.count({ where: { articleId: article.id } });
  if (count > 0) {
    return;
  }

  const comments = SEED_DATA.commentBodies.map((body) => ({
    body,
    articleId: article.id,
    userId: user.id,
  }));

  await Comment.bulkCreate(comments);
}

module.exports = { seed };

const UNKNOWN_AUTHOR = "unknown";

function getAuthorName(author) {
  return author?.username ?? UNKNOWN_AUTHOR;
}

function formatCommentDate(createdAt) {
  return createdAt ? new Date(createdAt).toLocaleDateString() : "";
}

function CommentRow({ body, author, createdAt }) {
  const username = getAuthorName(author);
  const date = formatCommentDate(createdAt);

  return (
    <div className="comment">
      <p className="comment-body">{body}</p>
      <p className="comment-meta">
        {username} · {date}
      </p>
    </div>
  );
}

export default CommentRow;

const { User, Article, ASSOCIATION_ALIASES } = require("./models");

const COMMENT_AUTHOR_INCLUDE = [
  { model: User, as: ASSOCIATION_ALIASES.author, attributes: ["username"] },
];

async function findCommentsByArticleSlug(slug) {
  const article = await Article.findOne({ where: { slug } });
  if (!article) {
    return null;
  }

  return article.getComments({
    include: COMMENT_AUTHOR_INCLUDE,
  });
}

module.exports = { findCommentsByArticleSlug };

const { findCommentsByArticleSlug } = require("./commentsService");
const { sendNotFound, sendServerError } = require("./httpResponses");

function registerRoutes(app) {
  app.get("/api/articles/:slug/comments", getArticleComments);
}

async function getArticleComments(req, res) {
  try {
    const { slug } = req.params;
    const comments = await findCommentsByArticleSlug(slug);
    if (!comments) {
      return sendNotFound(res);
    }

    res.json({ comments });
  } catch (error) {
    sendServerError(res, error);
  }
}

module.exports = { registerRoutes };

import { useEffect, useState } from "react";
import { getComments } from "./api";

function createEmptyState() {
  return {
    comments: [],
    error: null,
  };
}

function createLoadedState(comments) {
  return {
    comments,
    error: null,
  };
}

function createErrorState(error) {
  return {
    comments: [],
    error: error.message,
  };
}

function isAbortError(error) {
  return error.name === "AbortError";
}

function useComments(slug) {
  const [state, setState] = useState(createEmptyState);

  useEffect(() => {
    const controller = new AbortController();

    async function loadComments() {
      setState(createEmptyState());

      try {
        const comments = await getComments(slug, {
          signal: controller.signal,
        });

        if (!controller.signal.aborted) {
          setState(createLoadedState(comments));
        }
      } catch (error) {
        if (!controller.signal.aborted && !isAbortError(error)) {
          setState(createErrorState(error));
        }
      }
    }

    loadComments();

    return () => {
      controller.abort();
    };
  }, [slug]);

  return state;
}

export default useComments;

import CommentList from "./CommentList";
import useComments from "./useComments";

function CommentFeed({ slug }) {
  const { comments, error } = useComments(slug);

  if (error) return <p className="error">{error}</p>;
  if (comments.length === 0) return null;

  return <CommentList comments={comments} />;
}

export default CommentFeed;
import CommentRow from "./CommentRow";

function CommentList({ comments }) {
  return (
    <div className="feed">
      {comments.map((comment) => (
        <CommentRow key={comment.id} {...comment} />
      ))}
    </div>
  );
}

export default CommentList;

